const D = {"presenter": "a friendly woman, late twenties, natural makeup, shoulder-length brown hair, a casual cream knit sweater, in a bright modern bathroom with soft daylight", "voiceDelivery": "Warm, friendly and natural, like talking to a close friend", "voiceSample": "Okay, I have to tell you about the serum I've been using every morning.", "scene": "The presenter sits facing the camera at a bright bathroom vanity, relaxed and smiling, hands resting on the counter.", "intro": "Looking into the lens, the presenter says with a small excited smile: \"Okay, I have to show you my morning skincare routine.\"", "closing": "The presenter smiles into the lens and says: \"The link is below. Try it, you'll thank me later.\" Then gives a small wave."};
const P = [["Vitamin C serum", "a small amber glass dropper bottle with a white label reading GLOW C SERUM and a black rubber dropper top", "The presenter picks up the serum, holds it up so the label faces the camera, and says: \"This vitamin C serum goes on first every morning. Two drops, and my skin looks so much brighter.\""], ["Moisturizer", "a white frosted glass jar with a silver lid and a minimal label reading DAILY CLOUD CREAM", "The presenter picks up the moisturizer jar, lifts the lid to show the cream, and says: \"Then this moisturizer. It's light, it sinks in fast, and it lasts all day.\""], ["Sunscreen", "a slim white squeeze tube with an orange cap and a label reading SPF 50 DAILY SHIELD", "The presenter picks up the sunscreen tube, shows the label to the camera, and says: \"And I never skip sunscreen. This one leaves no white cast at all.\""], ["Cleanser", "a clear pump bottle of pale blue gel cleanser with a label reading GENTLE FOAM CLEANSER", "The presenter taps the top of the cleanser bottle and says: \"At night I start with this gentle cleanser. It takes everything off without drying my skin.\""], ["Face roller", "a green jade facial roller with a gold-colored metal handle", "The presenter picks up the jade roller, rolls it gently along one cheek, and says: \"And this jade roller is my little treat. Cold, calming, and great for puffiness.\""]];
const lengths = [{"option": "4 s"}, {"option": "6 s"}, {"option": "8 s"}, {"option": "10 s"}];
const fields = [];
if (s.presenterMode === 'generate') fields.push({ fieldLabel: 'Presenter', fieldType: 'textarea', requiredField: true, defaultValue: D.presenter });
if (s.presenterMode === 'upload') fields.push(
  { fieldType: 'html', html: '<p>Use a clear, front-facing photo. Google screens real faces, so a photo of a real person may be refused in video.</p>' },
  { fieldLabel: 'Presenter photo', fieldType: 'file', requiredField: true, multipleFiles: false, acceptFileTypes: '.png,.jpg,.jpeg,.webp' },
  { fieldLabel: 'Second presenter photo', fieldType: 'file', multipleFiles: false, acceptFileTypes: '.png,.jpg,.jpeg,.webp' },
  { fieldType: 'html', html: '<p>Optional: a three-quarter view. Without it, the next pages generate one from the first photo.</p>' });
if (s.presenterMode === 'character') fields.push(
  { fieldLabel: 'Character ID', fieldType: 'text', requiredField: true, placeholder: 'user:...-character:...  (shown on the last page of an earlier run)' },
  { fieldType: 'html', html: '<p>The saved character brings its own face and voice.</p>' });
if (s.presenterMode !== 'character') fields.push(
  { fieldLabel: 'Voice', fieldType: 'dropdown', requiredField: true, defaultValue: 'Female', fieldOptions: { values: [{ option: 'Female' }, { option: 'Male' }] } },
  { fieldLabel: 'Voice delivery', fieldType: 'text', requiredField: true, defaultValue: D.voiceDelivery },
  { fieldLabel: 'Voice sample line', fieldType: 'text', requiredField: true, defaultValue: D.voiceSample });
fields.push({ fieldLabel: 'Scene', fieldType: 'textarea', requiredField: true, defaultValue: D.scene });
if (s.intro) fields.push({ fieldType: 'html', html: '<h3>Intro clip</h3>' },
  { fieldLabel: 'Intro: what the presenter does and says', fieldType: 'textarea', requiredField: true, defaultValue: D.intro },
  { fieldLabel: 'Intro length', fieldType: 'dropdown', requiredField: true, defaultValue: '6 s', fieldOptions: { values: lengths } });
for (let i = 0; i < s.productCount; i++) { const [name, desc, action] = P[i]; const n = i + 1;
  fields.push({ fieldType: 'html', html: `<h3>Product ${n}</h3>` },
    { fieldLabel: `Product ${n} name`, fieldType: 'text', requiredField: true, defaultValue: name },
    { fieldLabel: `Product ${n} description`, fieldType: 'textarea', defaultValue: desc, placeholder: 'What it looks like. Can stay empty if you upload a photo.' },
    { fieldLabel: `Product ${n} photo`, fieldType: 'file', multipleFiles: false, acceptFileTypes: '.png,.jpg,.jpeg,.webp' },
    { fieldLabel: `Product ${n} 4-view sheet from the photo`, fieldType: 'dropdown', defaultValue: 'No', fieldOptions: { values: [{ option: 'No' }, { option: 'Yes' }] } },
    { fieldLabel: `Product ${n} clip: what the presenter does and says`, fieldType: 'textarea', requiredField: true, defaultValue: action },
    { fieldLabel: `Product ${n} clip length`, fieldType: 'dropdown', requiredField: true, defaultValue: '10 s', fieldOptions: { values: lengths } }); }
if (s.closing) fields.push({ fieldType: 'html', html: '<h3>Closing clip</h3>' },
  { fieldLabel: 'Closing: what the presenter does and says', fieldType: 'textarea', requiredField: true, defaultValue: D.closing },
  { fieldLabel: 'Closing length', fieldType: 'dropdown', requiredField: true, defaultValue: '6 s', fieldOptions: { values: lengths } });
