const fileKey = label => Object.keys(bin).find(k => norm(k) === norm(label));
const secs = v => Number(String(v || '10').replace(/[^0-9]/g, '')) || 10;
const uploads = [];
if (s.presenterMode === 'generate') s.presenterDesc = f['Presenter'];
if (s.presenterMode === 'upload') { uploads.push({ role: 'presenter1', key: fileKey('Presenter photo') });
  const k2 = fileKey('Second presenter photo'); if (k2) uploads.push({ role: 'presenter2', key: k2 }); }
if (s.presenterMode === 'character') s.character = String(f['Character ID'] || '').trim();
if (s.presenterMode !== 'character') { s.voiceGender = f['Voice']; s.voiceDelivery = String(f['Voice delivery']).slice(0, 120); s.voiceSample = String(f['Voice sample line']).slice(0, 120); }
s.scene = f['Scene'];
s.products = [];
for (let i = 0; i < s.productCount; i++) { const n = i + 1; const key = fileKey(`Product ${n} photo`);
  const name = String(f[`Product ${n} name`] || `Product ${n}`).trim();
  s.products.push({ name, desc: String(f[`Product ${n} description`] || '').trim() || name, sheet: f[`Product ${n} 4-view sheet from the photo`] === 'Yes',
    action: f[`Product ${n} clip: what the presenter does and says`], duration: secs(f[`Product ${n} clip length`]) });
  if (key) uploads.push({ role: 'product', index: i, key }); }
s.clips = [];
if (s.intro) s.clips.push({ name: 'Intro', action: f['Intro: what the presenter does and says'], duration: secs(f['Intro length']), product: null });
s.products.forEach((p, i) => s.clips.push({ name: `Product ${i + 1}`, action: p.action, duration: p.duration, product: i }));
if (s.closing) s.clips.push({ name: 'Closing', action: f['Closing: what the presenter does and says'], duration: secs(f['Closing length']), product: null });
return [{ json: { state: s, uploads, hasUploads: uploads.length > 0 }, binary: bin }];

const d = $input.first();  // straight from Read details through the IF: a file read via $('Read details') arrives empty
const s = d.json.state;
return d.json.uploads.map(u => ({ json: { email: s.email, role: u.role, index: u.index }, binary: { file: d.binary[u.key] } }));

