  s.tries[stage] = 0; return null; };
const failNote = (j, what) => kind(j) === 'refused'
  ? `<p><b>Google refused the ${what}:</b> ${errText(j)}</p><p>Change the description and re-roll. Refusals also vary between attempts.</p>`
