const img = (url, label) => `<td>${label}<br>${url ? `<a href="${url}" target="_blank" rel="noopener"><img src="${url}" alt="${label}"></a><br><a href="${url}" target="_blank" rel="noopener">open full size</a>` : '(no preview)'}</td>`;

