fields.push({ fieldLabel: 'Final video', fieldType: 'radio', requiredField: true, defaultValue: s.upscale === false ? 'Keep 720p' : 'Upscale to 1080p',
  fieldOptions: { values: [{ option: 'Upscale to 1080p' }, { option: 'Keep 720p' }] } });
return [{ json: { state: s, fields } }];

const s = $('Clip page').first().json.state;
const L = 'ABCD';
s.clipsPending = [];
s.clips.forEach((c, i) => { const v = $json[c.name]; const edit = $json[`New action for ${c.name}`];
  if (v === 'Re-roll') { if (edit && edit.trim()) c.action = edit.trim(); s.clipsPending.push(i); }
  else s.clipPicks[i] = s.clipTakes[i][L.indexOf(v.slice(-1))]; });
s.upscale = $json['Final video'] === 'Upscale to 1080p';
if ($json['If clips keep being refused'] === 'Pick a different scene') {
  // Google keeps refusing clips in this frame: go back and generate new scenes (the character and products stay).
  s.clipsPending = []; s.sceneNote = 'A calmer arrangement, with the products further from the presenter.';
  return [{ json: { state: s, route: 'scene' } }];
}
return [{ json: { state: s, reroll: s.clipsPending.length > 0, route: s.clipsPending.length ? 'reroll' : 'done' } }];

const s = $('Scene choice').last().json.state;
const c = $json.credits || {};
if (typeof c.credits === 'number' && c.credits < s.estimatedCredits)
  return [{ json: { route: 'stop', state: s, message: `The clips need about ${s.estimatedCredits} Flow credits, and ${s.email} now has ${c.credits}. Add credits, or start again with fewer takes or clips.` } }];
return [{ json: { route: 'ok', state: s } }];  // a failed read does not block: the clip submit reports its own errors

const s = $json.state;
s.upscaledIds = s.upscaledIds || {};
// Only clips not upscaled yet: "Retry upscaling" on the last page comes back here for the ones that failed.
const todo = s.upscale ? s.clipPicks.map((p, i) => i).filter(i => !s.upscaledIds[i]) : [];
if (!todo.length) return [{ json: { state: s, upscale: false } }];
return todo.map(i => ({ json: { state: s, index: i, upscale: true, body: { mediaGenerationId: s.clipPicks[i].id, resolution: '1080p', captchaRetry: s.captchaRetry } } }));

// The ad is served by this workflow's own download URL (the "Download ad" webhook), which joins the picked clips
// on request. Joining is free, so playing or downloading again simply joins again, and re-joining with new cut
// points (from the "Your ad" page) only rebuilds this page.
let s;
if ($json.rejoin) s = $json.state;
else {
  const reqs = $('Upscale requests').all();
  s = reqs[0].json.state;
  if (reqs[0].json.upscale) $input.all().forEach((it, k) => { const m = it.json.media && it.json.media[0]; if (m) s.upscaledIds[reqs[k].json.index] = m.mediaGenerationId; });
}
s.upscaledIds = s.upscaledIds || {};
s.trims = s.trims || s.clips.map(() => ({ start: 0.15, end: 0.3 }));
const ids = s.clipPicks.map((p, i) => s.upscaledIds[i] || p.id);  // a clip whose upscale failed stays at 720p
const stayed = s.upscale ? s.clips.filter((c, i) => !s.upscaledIds[i]).map(c => c.name) : [];
const media = ids.map((id, i) => ({ mediaGenerationId: id, trimStart: s.trims[i].start, trimEnd: s.trims[i].end }));
const origin = String($execution.resumeFormUrl || $execution.resumeUrl).match(/^https?:\/\/[^/]+/)[0];  // the Code sandbox has no URL class
const m = Buffer.from(JSON.stringify(media)).toString('base64url');
const play = `${origin}/webhook/ugc-ad-factory-download?m=${m}`;
const html = `<video controls><source src="${play}" type="video/mp4"></video><p><a href="${play}&dl=1" target="_blank" rel="noopener">Download the MP4</a> · <a href="${play}" target="_blank" rel="noopener">open in a new tab</a></p>
${stayed.length ? `<p><b>Note:</b> upscaling failed for ${stayed.join(', ')} (usually captcha), so ${stayed.length > 1 ? 'those clips are' : 'that clip is'} at 720p in this version. Upscaling is free: choose "Retry upscaling" below.</p>` : ''}
<p>The video is joined from your clips when you open it, which takes about half a minute. Your clips also stay in your Google Flow account.</p>
<p><b>Adjust the cuts.</b> If a join has a pause or clips a word, change how much is cut from the start or end of that clip, then choose "Re-join with these cuts". If a cut visibly jumps, trimming will not fix it: go back and pick a different take for that clip in your next run.</p>
<p><b>Reuse this presenter:</b> choose "Use a saved character" on the start form and paste this ID:<br><code>${s.character}</code></p>`;
const steps = ['0 s', '0.15 s', '0.3 s', '0.5 s', '0.75 s', '1 s', '1.25 s', '1.5 s', '2 s'].map(option => ({ option }));
const nearest = v => steps.map(o => o.option).reduce((a, b) => Math.abs(parseFloat(b) - v) < Math.abs(parseFloat(a) - v) ? b : a);
const fields = [{ fieldType: 'html', html: s.clips.length > 1 ? html : html.replace(/<p><b>Adjust the cuts.*?<\/p>/s, '') }];
if (s.clips.length > 1) s.clips.forEach((c, i) => {
  fields.push({ fieldLabel: `${c.name} (${c.duration} s): cut from start`, fieldType: 'dropdown', defaultValue: nearest(s.trims[i].start), fieldOptions: { values: steps } });
  fields.push({ fieldLabel: `${c.name} (${c.duration} s): cut from end`, fieldType: 'dropdown', defaultValue: nearest(s.trims[i].end), fieldOptions: { values: steps } });
});
const next = s.clips.length > 1 ? [{ option: 'Finish' }, { option: 'Re-join with these cuts' }] : [{ option: 'Finish' }];
if (stayed.length) next.unshift({ option: 'Retry upscaling the 720p clips' });
fields.push({ fieldLabel: 'Next', fieldType: 'radio', requiredField: true, defaultValue: next[0].option, fieldOptions: { values: next } });
s.trims = s.trims.map((t, i) => ({ start: parseFloat(nearest(t.start)), end: parseFloat(nearest(t.end)) }));
return [{ json: { state: s, fields } }];

const s = $('Final page').last().json.state;
const v = $json['Next'] || 'Finish';
// New cut points. The join rejects a clip whose two cuts add up to its whole length, so keep at least 1 s of every clip.
s.clips.forEach((c, i) => {
  const a = parseFloat($json[`${c.name} (${c.duration} s): cut from start`]), b = parseFloat($json[`${c.name} (${c.duration} s): cut from end`]);
  if (!isNaN(a)) s.trims[i].start = a;
  if (!isNaN(b)) s.trims[i].end = b;
  const over = s.trims[i].start + s.trims[i].end - (c.duration - 1);
  if (over > 0) s.trims[i].end = Math.max(0, s.trims[i].end - over);
});
const route = v.startsWith('Retry') ? 'retry' : v.startsWith('Re-join') ? 'rejoin' : 'done';
return [{ json: { state: s, route, rejoin: route === 'rejoin' } }];

const q = $json.query || {};
const media = JSON.parse(Buffer.from(String(q.m || ''), 'base64url').toString('utf8'));
// The join needs 2 to 10 clips, so a one-clip ad streams that clip directly.
return [{ json: { download: q.dl === '1', single: media.length === 1, id: media[0].mediaGenerationId, body: { media } } }];
